def merge(intervals):
    intervals.sort()
    out=[]
    for lo,hi in intervals:
        if out and lo <= out[-1][1]: out[-1][1]=hi
        else: out.append([lo,hi])
    return out

def get_path(data,path,default=None):
    for key in path.split("."):
        data=data.get(key) or default
    return data

def latest(events):
    out={}
    for event in events:
        if event["id"] not in out or event["ts"] > out[event["id"]]["ts"]: out[event["id"]]=event
    return out

